{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Cefditoren absolute oral bioavailability is approximately 14% under fasting conditions, below the 20% threshold and supporting a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "EM574 oral bioavailability in humans is estimated at 2% from oral clearance relative to hepatic blood flow, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Oseltamivir absolute oral bioavailability is 79% relative to an intravenous dose in volunteers, above the 20% threshold and arguing for high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest quantitative, ordinary-condition records are consistently low (cefditoren ~14%, EM574 ~2%), with additional absolute low-F evidence such as YH4808 ~10.1% and glycyrrhizin ~0.25%. High-F evidence from oseltamivir and etoposide is present but is outweighed by the higher-transferability low-F records and variability in some positive records. Therefore, low F (<20%) is better supported.",
  "evidence_gaps": [
    "Several low-bioavailability records are qualitative or from non-standard formulations (oat products, unformulated withaferin A), limiting direct quantitative threshold comparison.",
    "Positive records for terguride and etoposide show wide variability and dose/sex dependence, adding uncertainty to the high-F evidence.",
    "Molecule 4 provides only a possible low-bioavailability inference without a numeric F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

